#include <bits/stdc++.h>
using namespace std;
class Solution {public:bool checkStrings(string s1,string s2){for(int parity=0;parity<2;++parity){string a,b;for(int i=parity;i<(int)s1.size();i+=2){a+=s1[i];b+=s2[i];}sort(a.begin(),a.end());sort(b.begin(),b.end());if(a!=b)return false;}return true;}};
